    <section className="hero"><div className="heroWords"><div className="eyebrow"><span className="eyebrowLine"/>{l.tag}</div><h1>{l.hero}<br/><em>{l.hero2}</em></h1><p>{l.intro}</p><div className="heroButtons"><button className="filled" onClick={()=>navigate('explore')}>{l.start}<span>↗</span></button><button className="textButton" onClick={()=>navigate('learn')}>{l.learnCta}<span>→</span></button></div></div><div className="heroArtwork"><img className="growthVisual tradingBrandVisual" src="/trading27-logo-original.png" alt={language==='ca'?'Trading27: logotip t²⁷ i Trading amb una fletxa ascendent blava i cian':language==='es'?'Trading27: logotipo t²⁷ y Trading con flecha ascendente azul y cian':'Trading27 t²⁷ wordmark and blue-to-cyan rising arrow'}/></div></section>
